// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        // Not the current owner, so call will revert. We only test when call succeeds.
        vm.assume(_owner != c.owner());
        // First we need a valid owner call: we're the owner (msg.sender) from setup
        bool success = c.setOwner(_owner);
        assertTrue(success);
    }
}

